parameters.jsCode:
const raw = $input.all()[0].json.choices[0].message.content;
let lead = {};
try { lead = JSON.parse(raw); } catch(e) { lead = { score: 0, summary: 'parse error' }; }

const webhookData = $('Webhook').first().json;

return [{
  json: {
    name: webhookData.name || '',
    email: webhookData.email || '',
    company: webhookData.company || '',
    score: lead.score || 0,
    budget: lead.budget || '',
    urgency: lead.urgency || '',
    fit: lead.fit || '',
    summary: lead.summary || '',
    email_subject: lead.email_subject || '',
    email_body: lead.email_body || '',
    is_hot: (lead.score || 0) >= 7
  }
}];

